PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/void#>
SELECT ?zone ?zoneName ?tsid WHERE {
  ?ahu a brick:AirHandlingUnit ; brick:hasTag "AHU02" .
  ?ahu brick:feeds ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneName . }
  ?temp a brick:AirTemperatureSensor ; brick:hasLocation ?zone .
  ?temp ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?zone ?label WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU02> brick:feeds ?zone .
  OPTIONAL { ?zone rdfs:label ?label } .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?vav ?zone WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU02> brick:feeds ?vav .
  ?vav brick:feeds ?zone .
}

SELECT ?s ?p ?o WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#VAV_F3_Z01> ?p ?o .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor ?sensorcls ?zone ?label ?tsid WHERE {
  ?sensor brick:hasLocation ?zone .
  ?sensor a ?sensorcls .
  FILTER (?sensorcls = brick:Zone_Air_Temperature_Sensor || ?sensorcls = brick:Air_Temperature_Sensor)
  FILTER (STRSTARTS(STR(?zone), "http://buildgraph.org/BG_large_office_2004_0000#Zone_F3"))
  OPTIONAL { ?sensor rdfs:label ?label }
  OPTIONAL { ?sensor brick:ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?zonecls ?zone ?label ?tsid WHERE {
  ?sensor brick:hasLocation ?zone .
  FILTER (CONTAINS(STR(?sensor), "Zone_F3"))
  FILTER (CONTAINS(STR(?sensor), "Zone_Air_Temperature_Sensor") || CONTAINS(STR(?sensor), "Air_Temperature_Sensor"))
  OPTIONAL { ?sensor rdfs:label ?label }
  OPTIONAL { ?sensor ?t ?tsid . FILTER(STRSTARTS(STR(?t), "https://brickschema.org/schema/Brick/ref#hasTimeseriesId")) }
} LIMIT 40

SELECT ?sensor ?cls ?zone ?label ?tsid WHERE {
  ?sensor a ?cls .
  ?cls rdfs:subClassOf* ?c2 .
  FILTER (CONTAINS(STR(?sensor), "Zone_F3"))
  OPTIONAL { ?sensor rdfs:label ?label }
  OPTIONAL { ?sensor brick:ref:hasTimeseriesId ?tsid }
} LIMIT 60

SELECT ?sensor ?tsid WHERE {
  ?sensor a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
  FILTER (CONTAINS(STR(?sensor), "Zone_F3"))
  ?sensor brick:ref:hasTimeseriesId ?tsid .
}

SELECT ?sensor ?t ?tsid WHERE {
  ?sensor a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
  FILTER (CONTAINS(STR(?sensor), "Zone_F3"))
  ?sensor ?t ?tsid .
  FILTER (CONTAINS(STR(?t), "Timeseries"))
}

SELECT ?sensor ?t ?o WHERE {
  ?sensor a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
  FILTER (CONTAINS(STR(?sensor), "Zone_F3"))
  ?sensor ?t ?o .
}

SELECT ?ref ?t ?o WHERE {
  ?ref a brick:ref:TimeseriesReference .
  FILTER (CONTAINS(STR(?ref), "tsref"))
  ?ref ?t ?o .
} LIMIT 40

